@js:
仙女库 = cache.getFile('仙女库');
if(仙女库==null){仙女库=""
java.toast('缓存失效，正在重新获取发现')

//转化成新分类
function $$(title,url,type){
		if(type>0){
				if(type>1)title = '༺ˇ»`ʚ'+title+'ɞ´«ˇ༻';
				type = 'BasisPercent'
			}
		else{
				type = 'Grow'
			}
		return 仙女库 += '{"title":"'+title+'","url":\''+url+'\',"style":{"layout_flex'+type+'":1}},'
	}


//补全url
function $(uri,type,_){
		if(type==0){
				body = ''
			}
		else{
				body = '"body":"'
				if(type<4){
						//可以改成9999(获取全部的模特)
						body += 'pagesize=233&page=1'
					}
				else{
						body += 'pagesize=20&page={{page}\}'
						if(type==5){
								body += '&id='+_
							}
						else if(type==6){
								body += '&key='+_
							}
					}
				body += '",'
			}
		return 'http://apis.app125.com/api/lists/'+uri+',{'+body+'"method":"POST"}'
	}


$$("推荐","",2)
$$("精选",$('reco',4))
$$("最新",$('addtime',4))
$$("最热",$('hits',4))
$$("","",1);


[["热搜","resou"],["机构","jigou"],["分类","tags"],["模特","motel"]].map((j,i)=>{
java.toast('正在获取'+j[0])
		$$(j[0],"",2);
		ajax = java.ajax( $(j[1],i) );
JSON.parse(ajax).data.map(_=>{
		if(_.name!=undefined)
				$$(_.name,$(j[1]+'_type',5,_.id));
		else
				$$(_,$('search',6,_));
	});
		$$("","",1);
});
cache.putFile('仙女库',仙女库,1e6)
java.toast('发现获取成功，欢迎')
}

'['+String(仙女库).replace(/,$/,'')+']'

