source.jsLib:
var API='http://ilikeuaa.starseatech.top';
var hosts=[
  'https://cdn.uameta.ai/file/bucket-media',
  'https://cdn.uaa010.com/file/bucket-media',
  'https://cdn.uaa.com/file/bucket-media',
  'https://cdn.uaa202410.com/file/bucket-media'
];
function getApiKey(){
  var k='';
  try{k=source.getLoginHeader()||'';}catch(e){}
  return k;
}
function getHostIdx(){
  var d={};
  try{d=JSON.parse(source.getVariable()||'{}');}catch(e){}
  return parseInt(d.cdn||0);
}
function getFileUrl(path){
  if(!path)return '';
  if(path.startsWith('http'))return path;
  var idx=getHostIdx();
  if(idx<0||idx>=hosts.length)idx=0;
  return hosts[idx]+path;
}
function apiGet(path, params){
  var qs=[];
  for(var k in params)qs.push(k+'='+encodeURIComponent(params[k]));
  var url=API+path+'?'+qs.join('&');
  try{
    var resp=java.connect(url,{'X-API-Key':getApiKey()},15000);
    return JSON.parse(String(resp.body()));
  }catch(e){return {};}
}

source.loginUrl:
function login(){
  try{java.toast('正在登录…');}catch(e){}
  // 先同步输入框数据
  try{if(java.upLoginData)java.upLoginData();}catch(e){}
  var uname='',pwd='';
  // 方式1：从 result 读取
  try{
    if(result){
      uname=result['用户名']||result['username']||'';
      pwd=result['密码']||result['password']||'';
    }
  }catch(e){}
  // 方式2：从 source.getLoginInfoMap 读取
  if(!uname||!pwd){
    try{
      var map=source.getLoginInfoMap();
      if(typeof map.get==='function'){
        uname=uname||map.get('用户名')||'';
        pwd=pwd||map.get('密码')||'';
      }
    }catch(e){}
  }
  // 方式3：从 source.getLoginInfo 读取
  if(!uname||!pwd){
    try{
      var info=JSON.parse(source.getLoginInfo()||'{}');
      uname=uname||info['用户名']||info['username']||'';
      pwd=pwd||info['密码']||info['password']||'';
    }catch(e){}
  }
  if(!uname||!pwd){
    try{java.toast('请填写用户名和密码');}catch(e){}
    return;
  }
  // 保存账号密码
  try{source.putLoginInfo(JSON.stringify({'用户名':uname,'密码':pwd}));}catch(e){}
  try{
    var body='{"username":"'+uname+'","password":"'+pwd+'"}';
    var url='http://ilikeuaa.starseatech.top/api/auth/login,'+JSON.stringify({method:'POST',body:body,headers:{'Content-Type':'application/json'}});
    var resp=java.ajax(url,30000);
    var txt=String(resp);
    var idx=txt.indexOf('api_key');
    if(idx>-1){
      var s=txt.indexOf(':',idx)+2;
      var en=txt.indexOf('"',s);
      source.putLoginHeader(txt.substring(s,en));
      try{java.toast('登录成功！密钥已保存');}catch(x){}
    }else{
      try{java.toast('登录失败：'+txt.substring(0,100));}catch(x){}
    }
  }catch(x){
    try{java.toast('登录出错：'+x);}catch(z){}
  }
}
function register(){try{java.startBrowserAwait('http://ilikeuaa.starseatech.top/dashboard','注册账号');}catch(e){}}
function logout(){try{source.removeLoginHeader();}catch(e){}try{java.toast('已退出登录');}catch(e){}}
function toggleComments(){
  var d={};
  try{d=JSON.parse(source.getVariable()||'{}');}catch(e){}
  var on=d.comments!=='0';
  d.comments=on?'0':'1';
  source.setVariable(JSON.stringify(d));
  java.longToast(on?'段评已关闭':'段评已开启');
}
function setSearchType(t){
  var d={};
  try{d=JSON.parse(source.getVariable()||'{}');}catch(e){}
  if(t=='漫画')d.type='comic';
  else if(t=='音频')d.type='audio';
  else if(t=='视频')d.type='video';
  else d.type='novel';
  source.setVariable(JSON.stringify(d));
  java.longToast('搜索类型已切换为：'+t);
}
function setCDN(idx){
  var d={};
  try{d=JSON.parse(source.getVariable()||'{}');}catch(e){}
  d.cdn=idx;
  source.setVariable(JSON.stringify(d));
  java.longToast('CDN已切换为：'+(idx+1)+'号\n'+hosts[idx]);
}
function testCDN(){
  var results=[];
  var testPath='/image/cover/ce9de110f7ae4cc9b1f961d1f9621e86.jpg';
  for(var i=0;i<hosts.length;i++){
    var url=hosts[i]+testPath;
    var t=Date.now();
    try{
      var resp=java.connect(url,{},5000);
      var ms=Date.now()-t;
      var ok=resp&&resp.code()>=200&&resp.code()<400;
      results.push((i+1)+': '+(ok?'✅ '+ms+'ms':'❌ '+resp.code()));
    }catch(e){
      results.push((i+1)+': ❌ 超时');
    }
  }
  java.longToast('CDN测试结果：\n'+results.join('\n'));
}

